function navigateResults(event: ReactKeyboardEvent<HTMLElement>): void {
    if (event.nativeEvent.isComposing) return;
    const links = Array.from(dialogRef.current?.querySelectorAll<HTMLAnchorElement>(".command-palette__results a") ?? []);
    const current = links.indexOf(document.activeElement as HTMLAnchorElement);
    if (event.target === inputRef.current && event.key === "Enter") {
      event.preventDefault();
      links[0]?.click();
      return;
    }
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp" && !(current >= 0 && (event.key === "Home" || event.key === "End"))) return;
    event.preventDefault();
    if (!links.length) return;
    if (current === 0 && event.key === "ArrowUp") { inputRef.current?.focus(); return; }
    const index = event.key === "Home" ? 0 : event.key === "End" ? links.length - 1
      : current < 0 ? (event.key === "ArrowUp" ? links.length - 1 : 0)
      : Math.max(0, Math.min(links.length - 1, current + (event.key === "ArrowDown" ? 1 : -1)));
    links[index].focus();
    links[index].scrollIntoView({ block: "nearest" });
  }

  function chooseCommand(event: MouseEvent<HTMLAnchorElement>, item: CommandItem): void {
    const route = readAppRoute();
    const task = item.taskId ? pdfTasks.find((candidate) => candidate.id === item.taskId) : undefined;
    if (route.name === "workspace" && task) {
      event.preventDefault();
      const launch = getDocumentTaskLauncher(route.projectId);
      if (!launch) { setError("The document is still opening. Try again when it is ready."); return; }
      // Leave the document mounted until its current edits have been exported.
      closePalette();
      void launch(task);
      return;
    }
    closePalette();
  }

import type { PdfTask } from "../ia/taskCatalog";

type Launcher = (task: PdfTask) => Promise<void>;
const launchers = new Map<string, Launcher>();

/** All task entry points must use the mounted document's checked handoff.
 * Navigating first would unmount its live editor/form state before export. */
export function registerDocumentTaskLauncher(projectId: string, launcher: Launcher): () => void {
  launchers.set(projectId, launcher);
  return () => { if (launchers.get(projectId) === launcher) launchers.delete(projectId); };
}

export function getDocumentTaskLauncher(projectId: string): Launcher | undefined {
  return launchers.get(projectId);
}

const taskLauncherRef = useRef(chooseDocumentTask);
taskLauncherRef.current = chooseDocumentTask;
useEffect(() => registerDocumentTaskLauncher(projectId, (task) => taskLauncherRef.current(task)), [projectId]);

test("tool search supports arrow navigation, Enter, and empty results", async ({ page }) => {
  await page.goto("#/home");
  await page.getByRole("button", { name: "Open command palette" }).click();
  const dialog = page.getByRole("dialog", { name: "Find a PDF task", exact: true });
  const input = dialog.getByRole("textbox", { name: "Search PDF tasks" });
  await input.fill("zzzz-no-such-task");
  await input.press("Enter");
  await expect(dialog).toBeVisible();
  await input.fill("PDF");
  const links = dialog.getByRole("link");
  await input.press("ArrowDown");
  await expect(links.first()).toBeFocused();
  await page.keyboard.press("ArrowDown");
  await expect(links.nth(1)).toBeFocused();
  await page.keyboard.press("Home");
  await expect(links.first()).toBeFocused();
  await page.keyboard.press("ArrowUp");
  await expect(input).toBeFocused();
  await input.fill("remove pages");
  await input.press("Enter");
  await expect(page).toHaveURL(/#\/quick\/remove-pages$/);
  await expect(page.getByRole("heading", { name: "Remove pages", exact: true })).toBeVisible();
});

test("reader sidebar uses one labelled panel control instead of tab navigation", async ({ page }) => {
  await openSample(page);
  const panel = page.getByRole("combobox", { name: "Reader panel", exact: true });
  await panel.selectOption("info");
  await expect(page.locator("#viewer-sidebar-panel")).toBeVisible();
  await expect(page.locator("#viewer-sidebar-panel .info-list").first()).toBeVisible();
  await panel.selectOption("search");
  await expect(page.locator("#viewer-sidebar-panel input[type=search]")).toBeVisible();
  await expect(page.getByRole("tablist")).toHaveCount(0);
});


test("reader zoom keeps every button-selected scale visible", async ({ page }) => {
  await openSample(page);
  const zoom = page.getByRole("combobox", { name: "Zoom", exact: true });
  await zoom.selectOption("1.5");
  await page.getByRole("button", { name: "Zoom in", exact: true }).click();
  await expect(zoom.locator("option:checked")).toHaveText("175%");
  await zoom.selectOption("0.5");
  await page.getByRole("button", { name: "Zoom out", exact: true }).click();
  await expect(zoom.locator("option:checked")).toHaveText("25%");
  await zoom.selectOption("4");
  await page.getByRole("button", { name: "Zoom in", exact: true }).click();
  await expect(zoom.locator("option:checked")).toHaveText("400%");
});

async function continueWithCompression(page, entry) {
  if (entry === "tool search") {
    await page.keyboard.press("Control+k");
    const dialog = page.getByRole("dialog", { name: "Find a PDF task", exact: true });
    await dialog.getByRole("textbox", { name: "Search PDF tasks" }).fill("compress PDF");
    await expect(dialog.locator(".command-palette__results a").first().locator("strong")).toHaveText("Compress PDF");
    await dialog.getByRole("textbox", { name: "Search PDF tasks" }).press("Enter");
  } else {
    await page.getByRole("button", { name: "Document actions", exact: true }).click();
    await page.getByRole("dialog", { name: "Document actions" }).getByRole("button", { name: /^Compress PDF/ }).click();
  }
}

import { describe, expect, it, vi } from "vitest";
import { getDocumentTaskLauncher, registerDocumentTaskLauncher } from "../../src/product/documentTaskLauncher";
import { getTask } from "../../src/ia/taskCatalog";

describe("document task launch ownership", () => {
  it("routes commands through the live document and removes the launcher on exit", async () => {
    const launcher = vi.fn(async () => undefined);
    const remove = registerDocumentTaskLauncher("live-project", launcher);
    const task = getTask("compress-pdf")!;
    await getDocumentTaskLauncher("live-project")!(task);
    expect(launcher).toHaveBeenCalledWith(task);
    remove();
    expect(getDocumentTaskLauncher("live-project")).toBeUndefined();
  });
  it("old cleanup cannot unregister a new mounted document provider", () => {
    const removeOld = registerDocumentTaskLauncher("reopened", async () => undefined);
    const latest = vi.fn(async () => undefined);
    const removeNew = registerDocumentTaskLauncher("reopened", latest);
    removeOld();
    expect(getDocumentTaskLauncher("reopened")).toBe(latest);
    expect(getDocumentTaskLauncher("other-project")).toBeUndefined();
    removeNew();
  });
});
